struct HashTable { table: Vec<Vec<Item>> }
impl HashTable {
    fn new(size: usize) -> Self { Self { table: (0..size).map(|_| Vec::new()).collect() } }
    fn hash(&self, key: usize) -> usize { key % self.table.len() }
    fn set(&mut self, key: usize, value: String) {
        let index = self.hash(key);
        let bucket = &mut self.table[index];
        if let Some(item) = bucket.iter_mut().find(|item| item.key == key) { item.value = value; return; }
        bucket.push(Item { key, value });
    }
    fn get(&self, key: usize) -> Result<&str, &'static str> {
        self.table[self.hash(key)].iter().find(|item| item.key == key).map(|item| item.value.as_str()).ok_or("Key not found")
    }
    fn remove(&mut self, key: usize) -> Result<(), &'static str> {
        let index = self.hash(key);
        let bucket = &mut self.table[index];
        let index = bucket.iter().position(|item| item.key == key).ok_or("Key not found")?;
        bucket.remove(index); Ok(())
    }
}

use std::collections::{HashMap, VecDeque};
struct Node { query: String, results: String }
struct Cache { max_size: usize, lookup: HashMap<String, Node>, order: VecDeque<String> }
impl Cache {
    fn new(max_size: usize) -> Self { Self { max_size, lookup: HashMap::new(), order: VecDeque::new() } }
    fn move_to_front(&mut self, query: &str) { self.order.retain(|key| key != query); self.order.push_front(query.to_owned()); }
    /// Get a stored query result. Access moves its key to the front of the LRU list.
    fn get(&mut self, query: &str) -> Option<&str> {
        if self.lookup.contains_key(query) { self.move_to_front(query); }
        self.lookup.get(query).map(|node| node.results.as_str())
    }
    /// Set a result. A full cache removes its oldest entry before insertion.
    fn set(&mut self, query: String, results: String) {
        if let Some(node) = self.lookup.get_mut(&query) { node.results = results; self.move_to_front(&query); return; }
        if self.lookup.len() == self.max_size { if let Some(oldest) = self.order.pop_back() { self.lookup.remove(&oldest); } }
        self.order.push_front(query.clone()); self.lookup.insert(query.clone(), Node { query, results });
    }
}

